// TypeScript example: streaming generator + tool call + structured schema
interface Envelope<T = any> {
  kind: 'message' | 'tool_call' | 'tool_result';
  id: string;
  payload: T;
  metadata?: Record<string, any>;
}

// Structured output schema example (JSON Schema)
const orderSchema = { type: 'object', properties: { total: { type: 'number' }, items: { type: 'array' } }, required: ['total', 'items'] } as const;

// Streaming API (async generator)
async function* streamCompletion(input: string): AsyncGenerator<Envelope, void, unknown> {
  // SDK will yield ordered Envelope chunks as they arrive from the runtime
  // Example yield:
  yield { kind: 'message', id: 'env_1', payload: { text: 'Hello' } }
}

// Tool call example
const toolCall: Envelope = { kind: 'tool_call', id: 'env_2', payload: { name: 'getInventory', args: { sku: 'SKU123', qty: 5 } } }

// Consumer code (high-level)
for await (const chunk of streamCompletion('Create an order for 5 items SKU123')) {
  if (chunk.kind === 'tool_call') {
    const { name, args } = chunk.payload;
    // run tool and then send tool_result envelope back via SDK runtime
  }
  if (chunk.kind === 'message' && chunk.payload.text) {
    // streaming UI append chunk.payload.text
  }
}

go_example:
// Go example: channel-based streaming + structs for tool calls + JSON Schema validation (via github.com/some/jsonschema)
package sdkexample

import (
  "encoding/json"
)

type Envelope struct {
  Kind string `json:"kind"`
  ID string `json:"id"`
  Payload json.RawMessage `json:"payload"`
}

// ToolCallPayload example struct
type ToolCallPayload struct {
  Name string `json:"name"`
  Args json.RawMessage `json:"args"`
}

// Streaming client returns a read-only channel of Envelope pointers
func StreamCompletion(prompt string) <-chan *Envelope {
  ch := make(chan *Envelope)
  go func() {
    ch <- &Envelope{Kind: "message", ID: "env_1", Payload: json.RawMessage([]byte(`{"text":"hi"}`))}
    ch <- &Envelope{Kind: "tool_call", ID: "env_2", Payload: json.RawMessage([]byte(`{"name":"getUser","args":{"id":123}}`))}
    close(ch)
  }()
  return ch
}
